impl Manifest {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub(crate) fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"component\":");
		crate::codec::json_escape(&self.component, out);
		out.push(',');
		out.push_str("\"requested\":");
		out.push('[');
		let mut v24 = true;
		for v23 in self.requested.iter() {
			if !v24 {
				out.push(',');
			}
			v24 = false;
			v23.to_json_into(out);
		}
		out.push(']');
		out.push(',');
		out.push_str("\"grants\":");
		out.push('[');
		let mut v26 = true;
		for v25 in self.grants.iter() {
			if !v26 {
				out.push(',');
			}
			v26 = false;
			v25.to_json_into(out);
		}
		out.push(']');
		out.push('}');
	}
	pub(crate) fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("component=");
		out.push_str(&self.component);
		out.push_str(", ");
		out.push_str("requested=");
		out.push('[');
		let mut v28 = true;
		for v27 in self.requested.iter() {
			if !v28 {
				out.push_str(", ");
			}
			v28 = false;
			v27.to_text_into(out);
		}
		out.push(']');
		out.push_str(", ");
		out.push_str("grants=");
		out.push('[');
		let mut v30 = true;
		for v29 in self.grants.iter() {
			if !v30 {
				out.push_str(", ");
			}
			v30 = false;
			v29.to_text_into(out);
		}
		out.push(']');
		out.push('}');
	}
	pub(crate) fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 3);
		crate::codec::cbor::text(out, "component");
		crate::codec::cbor::text(out, &self.component);
		crate::codec::cbor::text(out, "requested");
		crate::codec::cbor::array(out, self.requested.len());
		for v31 in self.requested.iter() {
			v31.to_cbor_into(out);
		}
		crate::codec::cbor::text(out, "grants");
		crate::codec::cbor::array(out, self.grants.len());
		for v32 in self.grants.iter() {
			v32.to_cbor_into(out);
		}
	}
}

